using System;

public class Program
{
    public static void Main()
    {
        int[] points = { 12, 10, 8, 7, 6, 5, 4, 3, 2, 1 };
        int[] sum = new int[21];
        for (int judge = 1; judge <= 10; judge++)
        {
            for (int place = 0; place < 10; place++)
            {
                int song = int.Parse(Console.ReadLine());
                sum[song] += points[place];
            }
        }
        for (int k = 1; k <= 3; k++)
        {
            int best = 1;
            for (int s = 2; s <= 20; s++)
                if (sum[s] > sum[best])
                    best = s;
            Console.WriteLine(best);
            sum[best] = -1;
        }
    }
}

